intentos.respuesta_cruda:
{
  "sql": "SELECT t.categoria_ingles, t.pct_pagos_a_plazos FROM ( SELECT COALESCE(pt.product_category_name_english, 'sin_categoria') AS categoria_ingles, SUM(CASE WHEN p.payment_installments > 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(DISTINCT o.order_id) AS pct_pagos_a_plazos FROM order_payments p JOIN orders o ON p.order_id = o.order_id JOIN order_items oi ON o.order_id = oi.order_id LEFT JOIN product_category_translation pt ON oi.product_id = pt.product_id WHERE o.order_status NOT IN ('canceled', 'unavailable') AND p.payment_type != 'not_defined' GROUP BY categoria_ingles HAVING COUNT(DISTINCT o.order_id) >= 100 ) t ORDER BY t.pct_pagos_a_plazos DESC LIMIT 1"
}
